package com.movieticket.gateway;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.filter.GlobalFilter; import org.springframework.core.Ordered; import org.springframework.http.HttpHeaders; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets;
@Component public class JwtAuthenticationFilter implements GlobalFilter, Ordered {
 private final SecretKey key; public JwtAuthenticationFilter(@Value("${app.jwt.secret}") String secret){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}
 @Override public Mono<Void> filter(ServerWebExchange exchange, org.springframework.cloud.gateway.filter.GatewayFilterChain chain){String path=exchange.getRequest().getURI().getPath(); if(path.startsWith("/api/auth/")||path.equals("/actuator/health")) return chain.filter(exchange); String h=exchange.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION); if(h==null||!h.startsWith("Bearer ")) return unauthorized(exchange); try {Claims c=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload(); String subject=c.getSubject(); if(subject==null||subject.isBlank()) return unauthorized(exchange); var request=exchange.getRequest().mutate().header("X-Authenticated-User",subject).build(); return chain.filter(exchange.mutate().request(request).build());}catch(Exception ex){return unauthorized(exchange);} }
 private Mono<Void> unauthorized(ServerWebExchange e){e.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED); return e.getResponse().setComplete();} @Override public int getOrder(){return -100;}
}
